      <span
        className="absolute -right-1 -top-2 text-[72px] font-black leading-none select-none pointer-events-none"
        style={{ color: 'rgba(0,0,0,0.045)', letterSpacing: '-0.04em' }}
        aria-hidden="true"
      >
        {rank}
      </span>

